module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum_reg;
reg [DATA_WIDTH:0] sum_next;
reg [STG_WIDTH-1:0] stage_en;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= {DATA_WIDTH{1'b0}};
        stage_en <= {STG_WIDTH{1'b0}};
        o_en <= 1'b0;
    end else begin
        if (i_en) begin
            sum_next <= adda + addb;
            stage_en <= {STG_WIDTH{1'b1}};
        end else begin
            sum_next <= sum_reg;
            stage_en <= {STG_WIDTH{1'b0}};
        end
        sum_reg <= sum_next;
        o_en <= |stage_en;
    end
end

assign result = sum_reg;

endmodule
